// Hot batch 302: seventy-eight to eighty-instruction functions no route reaches, written by hand from `tools.disasm`
// and verified by synthetic cases (script bridges with string temporaries, lazy setup, slot resets, a heap adjust,
// member-pointer calls, struct copies and a recursive binary search by name).
// No names: none has evidence.
#include "decomp_registry.hpp"
#include "gt/game/hot_common.hpp"
#include "guest_call.hpp"

#include <bit>
#include <cstdint>
#include <utility>

